// SETTINGS: the two things to edit.
const HUB_URL = 'https://REPLACE-WITH-THE-HUB-ADDRESS';   // no trailing slash
const SOURCE = 'n8n-demo';                                // the source name registered in the hub

// A pretend failure from one of the apps Diego's flows touch. Each one says which app,
// what the code was, and what a person should do about it.
const ERRORS = [
  { app: 'Shopify', code: '429', message: 'Rate limit exceeded while syncing orders', action: 'Wait 60 seconds, then rerun. If it repeats, cut the sync batch size to 20.' },
  { app: 'Google Sheets', code: '403', message: 'Permission denied on the Orders sheet', action: 'Share the sheet with the n8n service account email, then rerun.' },
  { app: 'ClickUp', code: '404', message: 'List not found when creating a task', action: 'The list was moved or deleted. Pick the new list id in the ClickUp node.' },
  { app: 'Gmail', code: '401', message: 'OAuth token expired', action: 'Reconnect the Google credential in n8n, then rerun.' },
  { app: 'Facebook Graph', code: '190', message: 'Access token has expired', action: 'Generate a new page token and update the Facebook credential.' },
  { app: 'Instagram', code: '9007', message: 'Media is not ready to publish', action: 'Wait for the upload to finish processing, then rerun the publish step.' },
  { app: 'Stripe', code: '401', message: 'Invalid API key provided', action: 'Replace the secret key in the Stripe credential. Do not paste it in chat.' },
  { app: 'Supplier API', code: '503', message: 'Service unavailable', action: 'Nothing to fix on our side. The hub will retry. Contact the supplier if it ends as Gave up.' }
];
const pick = ERRORS[Math.floor(Math.random() * ERRORS.length)];

const EVENT = {
  flow: 'Order sync (example)',
  app: pick.app,
  code: pick.code,
  action: pick.action,
  error: `${pick.app} ${pick.code}: ${pick.message}. To do: ${pick.action}`,
};
// One key per event. A random part keeps two errors in the same millisecond apart.
const KEY = `err-${Date.now()}-${Math.floor(Math.random() * 1e6)}`;

const body = JSON.stringify(EVENT);
const timestamp = String(Math.floor(Date.now() / 1000));

return [{ json: { url: `${HUB_URL}/ingest/${SOURCE}`, key: KEY, timestamp, body, toSign: `${timestamp}\n${KEY}\n${body}` } }];
